export type GlossaryCategory = (typeof GLOSSARY_CATEGORIES)[number];

export type GlossaryEntry = {
  term: string;
  abbreviation?: string;
  category: GlossaryCategory;
  definition: string;
  founderNote?: string;
  aliases?: string[];
  formula?: string;
  learnMore?: { label: string; href: string };
};

const entry = (
  term: string,
  abbreviation: string | undefined,
  category: GlossaryCategory,
  definition: string,
  founderNote?: string,
  aliases?: string[],
  formula?: string,
  learnMore?: GlossaryEntry["learnMore"],
): GlossaryEntry => ({ term, abbreviation, category, definition, founderNote, aliases, formula, learnMore });

